import {Component, EventEmitter, Output} from '@angular/core';
import {FormBuilder, FormGroup, ReactiveFormsModule, Validators} from "@angular/forms";
import {TaskModel} from "../../shared/task.model";
import {NgClass} from "@angular/common";
import {InputValidatorComponent} from "../input-validator/input-validator.component";
import {TaskService} from "../../services/task.service";

@Component({
  selector: 'app-create-task',
  standalone: true,
  imports: [
    ReactiveFormsModule,
    NgClass,
    InputValidatorComponent,
  ],
  templateUrl: './create-task.component.html',
  styleUrl: './create-task.component.scss'
})
export class CreateTaskComponent {
  currentTask: FormGroup = this.fb.group({
    id: [this.taskService.taskSubject.getValue().length + 1],
    title: ['', [Validators.required, Validators.minLength(5)]],
    description: ['', [Validators.required, Validators.minLength(10)]],
    type: ['', [Validators.required]],
    status: ['', [Validators.required]],
    createdOn: ['', [Validators.required]],
  });

  constructor(private fb: FormBuilder, private taskService: TaskService) {
  }

  onSubmit(): void {
    this.taskService.addTask(this.currentTask.value);
    this.currentTask.reset();
  }

  get title() {
    return this.currentTask.get('title');
  }

  get description() {
    return this.currentTask.get('description');
  }

  get type() {
    return this.currentTask.get('type');
  }

  get status() {
    return this.currentTask.get('status');
  }

  get createdOn() {
    return this.currentTask.get('createdOn');
  }
}
<form [formGroup]="currentTask" (ngSubmit)="onSubmit()">

  <div class="form-layout">
    <div>
      <label for="title">Title:</label>
      <input id="title" type="text" formControlName="title" required>
      <app-input-validator [property]="title" [minLength]="5"></app-input-validator>
    </div>

    <div>
      <label for="description">Description:</label>
      <input id="description" type="text" formControlName="description" required>
      <app-input-validator [property]="description" [minLength]="10"></app-input-validator>
    </div>

    <div>
      <label for="type">Type:</label>
      <input id="type" type="text" formControlName="type" required>
      <app-input-validator [property]="type"></app-input-validator>
    </div>

    <div>
      <label for="status">Status:</label>
      <input id="status" type="text" formControlName="status" required>
    </div>
    <app-input-validator [property]="status"></app-input-validator>
  </div>

  <div>
    <label for="createdOn">Created On:</label>
    <input id="createdOn" type="text" formControlName="createdOn" required>
    <app-input-validator [property]="createdOn"></app-input-validator>
  </div>

  <button [ngClass]="{'enabled-button': currentTask.valid, 'disabled-button':!currentTask.valid}"
          [disabled]="!currentTask.valid" type="submit">Submit
  </button>

</form>
